    network:'<path d="M40 40L150 40L95 110Z M40 40L95 65L150 40 M95 65L95 110"/><circle cx="40" cy="40" r="14"/><circle cx="150" cy="40" r="14"/><circle cx="95" cy="110" r="14"/><circle cx="95" cy="65" r="14" class="accent"/>',
    profiles:'<path d="M20 110H180 M25 20V110"/><path d="M30 90L75 60L125 80L175 30"/><path d="M30 50L75 75L125 35L175 60" class="accent"/><circle cx="75" cy="60" r="4"/><circle cx="125" cy="35" r="4"/>',
