function researchComplementaryPage(){
  const groups=[
    ['distribution','¿La asociación cambia según el nivel de servicios?','Las regresiones cuantílicas examinan partes distintas de la distribución. La curva segmentada o no lineal busca cambios de pendiente.','Una pendiente media puede ocultar patrones entre países con puntuaciones bajas y altas.','No identifica umbrales clínicos ni prueba etapas de desarrollo.',['13_cuantilica','19c_segmentado','29e_curvilineo']],
    ['network','¿Qué dimensiones comparten información?','Correlaciones y redes muestran relaciones marginales o condicionadas; la centralidad resume la posición de un nodo en esa red.','Permite detectar conexiones y solapamiento entre indicadores.','Una conexión no es una dirección causal; centralidad no equivale a prioridad de intervención.',['07_correlaciones','15_ggm','29f_centralidad_ggm']],
    ['profiles','¿Hay perfiles de países con patrones parecidos?','El análisis de perfiles agrupa combinaciones de puntuaciones. Se comparan las configuraciones, no solo la media regional.','Ayuda a describir heterogeneidad dentro de una misma población.','Los grupos dependen del modelo, del tamaño y de los indicadores. No son categorías naturales demostradas.',['16_lpa']],
    ['configurations','¿Pueden existir distintas combinaciones asociadas al mismo resultado?','fsQCA examina configuraciones mediante calibración y reglas de consistencia y cobertura. Su sensibilidad revisa esas elecciones.','Explora condiciones conjuntas y posibles rutas alternativas hacia un nivel de servicios.','Consistencia fsQCA no es probabilidad, p estadístico ni estimación de un efecto SEM.',['14_fsqca','14b_fsqca_sensibilidad']],
    ['influence','¿Depende el patrón de un país o de unos pocos valores?','Omisiones, jackknife y diagnósticos de atípicos muestran cuánto se mueve la estimación.','Localiza observaciones influyentes y ayuda a entender su contexto.','Influencia no implica error del dato; eliminar un país cambia la población analizada.',['23_outliers','29c_jackknife_paises']],
    ['context','¿Qué ocurre al incorporar contexto nacional?','Covariables, moderaciones y análisis espacial examinan información contextual, diferencias de pendiente y dependencia territorial.','Investiga explicaciones alternativas y patrones que el modelo básico no contempla.','El ajuste disponible no elimina toda la confusión; el análisis sigue siendo transversal.',['40a_covariables_sociologicas','19b_moderaciones','20_espacial','40b_brecha_urbano_rural']],
    ['intervals','¿Una asociación pequeña puede considerarse compatible con equivalencia?','TOST contrasta límites de equivalencia definidos. La dominancia distribuye contribuciones al ajuste entre predictores.','Distingue ausencia de evidencia de una hipótesis explícita de efecto suficientemente pequeño.','Una p no significativa no demuestra equivalencia. Dominancia no es contribución causal.',['29b_tost','29a_dominancia']],
    ['prediction','¿Qué variables ayudan a predecir y generalizar?','LASSO regulariza coeficientes. La validación externa y el transporte contrastan resultados o predicciones bajo condiciones de comparabilidad.','Distingue descripción dentro de muestra de rendimiento fuera de ella.','Las definiciones incompatibles o cohortes solapadas pueden impedir el contraste. No se sustituyen por un cero.',['17_lasso','34_validacion_externa_i13']],
    ['curve','¿Cuánto cambia la lectura al cambiar la construcción?','Un constructo único y modelos seriales examinan agregaciones y descomposiciones alternativas.','Muestra qué parte del relato depende de separar dimensiones o imponer un orden.','El mejor ajuste no selecciona por sí solo una secuencia temporal ni una explicación causal.',['32_constructo_unico','29d_factor_unico','19a_mediacion_serial','25_process_tracing']]
  ];
  return heading('Otras preguntas que ayudan a entender el resultado','Cada familia de análisis aporta una pieza distinta. Elige la pregunta antes de elegir la técnica.')+
    `<div class="controls">${units()}${samples()}</div>`+
    researchProcess([['Detectar un patrón','Una asociación principal abre preguntas sobre heterogeneidad, influencia y contexto.'],['Escoger una comprobación','Relaciona cada técnica con la pregunta que realmente puede responder.'],['Volver al resultado principal','Explica qué cambia y qué permanece, sin sumar métodos como votos independientes.']])+
    `<div class="analysis-stories">${groups.map(([icon,title,how,use,limit,methods])=>{
      const records=CAT.filter(r=>r.unit===state.unit&&r.sample===state.sample&&methods.includes(r.method));
      const figures=records.flatMap(r=>r.figures.map(f=>({...f,record:r}))).slice(0,2);
      return `<section class="analysis-story"><div class="analysis-illustration">${researchVisualExample(icon)}<small>Esquema conceptual</small></div><div class="analysis-explanation"><h2>${title}</h2><p>${how}</p><dl><dt>Para qué sirve</dt><dd>${use}</dd><dt>Hasta dónde llega</dt><dd>${limit}</dd></dl><div class="row-links">${methods.map(m=>recordsLink(state.unit,m)).join('')}</div><details><summary>Estado de los análisis de esta selección</summary><ul>${records.map(r=>`<li>${esc(titleMethod(r.method))} · ${esc(r.scope)}: <strong>${r.state}</strong>${r.reason?' · '+esc(r.reason):''}</li>`).join('')||'<li>Sin resultados para esta población y muestra.</li>'}</ul></details></div>${figures.length?`<div class="analysis-results">${figures.map(f=>`<figure><a href="${f.url}" target="_blank" rel="noopener"><img loading="lazy" src="${f.url}" alt="${esc(titleMethod(f.record.method))} · ${esc(unitName(state.unit))}"></a><figcaption>${esc(titleMethod(f.record.method))} · ${esc(f.record.scope)}<br><button data-open="${f.record.id}">Leer figura y resultado original</button></figcaption></figure>`).join('')}</div>`:'<div class="analysis-results empty">Esta selección no tiene una figura disponible. Consulta el estado y el motivo del análisis.</div>'}</section>`;
    }).join('')}</div>`+
    panel('Comparaciones entre poblaciones y transporte',`<p>Los contrastes multigrupo, Chow, multinivel, Simpson y transporte conservan sus resultados en el archivo. Regiones y mundo pueden compartir países; la codificación curada y global de I13 también difiere. La comparabilidad se comprueba antes de interpretar una diferencia.</p>${recordsLink('comparativa','')}`);
}

function researchSimulationPage(){
  const all=D.tables.simulation_metrics,qs=unique(all.map(r=>r.estimando));if(!qs.includes(state.simquantity))state.simquantity='EI1';
  if(!['cobertura95','sesgo','rmse','convergencia','tipo_s','tipo_m'].includes(state.simmetric))state.simmetric='cobertura95';
  const choices=(key,labels={})=>({'':'Todas',...Object.fromEntries(unique(all.map(r=>r[key])).map(v=>[v,labels[v]||v]))});
  return heading('Qué nos dicen las simulaciones sobre el procedimiento','Experimentos con una verdad conocida: permiten medir error y calibración en los escenarios efectivamente generados.')+
    researchProcess([['Generar un mundo conocido','Se fijan relaciones, tamaño, correlación y faltantes. Se conoce la cantidad de referencia.'],['Repetir el análisis','Se producen muestras nuevas y se aplica cada procedimiento con la misma receta.'],['Comparar con la verdad','Se cuentan intervalos que la contienen, fallos, sesgo y variabilidad.']])+
    `<div class="simulation-designs"><article><h2>Diseño calibrado con el atlas</h2><strong>72 celdas × 1.000 repeticiones</strong><p>C1 · m=5 · B=500 · N=35, 50, 100 y 201 · magnitud nula, mitad y observada · correlación observada o reducida · heterogeneidad homogénea o regional · faltantes ninguno, MCAR o MNAR, según la celda.</p><p>Compara imputación múltiple, casos completos y una referencia con datos completos. Las verdades y denominadores se conservan por celda y cantidad.</p></article><article><h2>Evaluación conjunta de intervalos</h2><strong>7 escenarios × 400 repeticiones</strong><p>C1 continuo · N=35 o 184 · m=5 · B=499 · datos completos, MAR, resultado nulo, componente formativo, no linealidad y MNAR.</p><p>Compara percentil, BCa y Rubin donde corresponde. Incluye cobertura condicionada a intervalos válidos y cobertura sobre todos los intentos.</p></article></div>`+
    notice('Estos diseños tienen generadores, cantidades y denominadores distintos. No se suman sus repeticiones ni se extiende su cobertura automáticamente a C9 o a todas las regiones empíricas.',true)+
    panel('Explorar las 72 celdas',`<div class="controls">${select('simquantity','Cantidad',Object.fromEntries(qs.map(q=>[q,researchPath(q)])))}${select('simmetric','Medida',{cobertura95:'Cobertura 95 %',sesgo:'Sesgo',rmse:'RMSE',convergencia:'Convergencia',tipo_s:'Error de signo',tipo_m:'Error de magnitud'})}${select('simN','Tamaño N',choices('n'))}${select('simMissing','Faltantes',choices('faltantes',{ninguno:'Sin faltantes',mcar:'MCAR · aleatorios',mnar:'MNAR · dependen de valores'}))}${select('simMagnitude','Magnitud',choices('magnitud'))}${select('simCorrelation','Correlación',choices('correlacion'))}${select('simHeterogeneity','Heterogeneidad',choices('heterogeneidad'))}${select('simEstimator','Estimador',choices('estimador',RESEARCH_ESTIMATORS))}</div><div id="simulation-reading"></div><div id="simulation-chart" class="chart tall"></div><p class="metric-note">Cada posición horizontal identifica una celda. Las barras de error, cuando están disponibles, muestran ±1,96 errores Monte Carlo de la métrica; no son intervalos de coeficientes empíricos. La línea 0,95 indica la cobertura nominal.</p><div id="simulation-table"></div>`)+
    panel('Cómo interpretar cada medida',`<div class="interpretation-examples"><article>${researchVisualExample('intervals')}<h3>Cobertura</h3><p>Proporción de intervalos que contienen la verdad generada. Un 0,95 significa que la contienen 95 de cada 100 intervalos válidos aproximadamente. Lee también cuántos intentos produjeron un intervalo.</p></article><article>${researchVisualExample('prediction')}<h3>Sesgo y RMSE</h3><p>Sesgo = promedio estimado menos verdad. RMSE combina desviación y variabilidad: cuanto menor, más cerca quedan las estimaciones en ese escenario. Las escalas importan.</p></article><article>${researchVisualExample('influence')}<h3>Signo, magnitud y fallos</h3><p>Los errores de signo y de magnitud se condicionan a la regla de selección declarada. Un factor de magnitud de 2 indica una estimación absoluta doble de la verdad entre los resultados seleccionados. Si la verdad es cero, el cociente no está definido.</p></article></div>`)+
    panel('Evaluación conjunta: siete escenarios',`<div class="scenario-ribbon">${[['A_complete35','Sin faltantes · N35'],['A_MAR35','MAR · N35'],['A_MAR184','MAR · N184'],['A_null_MAR35','Resultado nulo · MAR'],['B_formative35','Componente formativo'],['C_nonlinear35','Respuesta no lineal'],['D_MNAR35','MNAR · N35']].map(([code,label])=>`<span><strong>${label}</strong><small>${code}</small></span>`).join('')}</div><p>En MAR, los faltantes dependen de información observada; en MNAR, de valores que pueden faltar. I13 permanece observado en este experimento. La celda de resultado nulo no anula las pendientes de gobernanza a los intermediarios.</p><div class="controls">${select('simspec','Cantidad conjunta',Object.fromEntries(unique(D.tables.joint_metrics.map(r=>r.quantity)).map(q=>[q,researchPath(q)])))}</div><div class="controls">${select('jointMetric','Medida conjunta',{coverage_conditional:'Cobertura entre intervalos válidos',coverage_all_attempts:'Cobertura sobre intentos',interval_failure:'Fallos de intervalo',bias:'Sesgo',rmse:'RMSE'})}</div><div id="joint-simulation-chart" class="chart tall"></div><div id="joint-simulation-reading"></div><div id="joint-simulation-table"></div>`)+
    panel('Denominadores y límites de lectura',researchProcess([['Intentos','Todas las repeticiones previstas, incluidas las que no produjeron un intervalo válido.'],['Intervalos válidos','Subconjunto en el que la cantidad pudo evaluarse. Ocultar fallos puede mejorar artificialmente la apariencia de cobertura.'],['Error Monte Carlo','La simulación también tiene incertidumbre. Con 400 intentos, el máximo error estándar de una proporción es 0,025; con 1.000, aproximadamente 0,016.']])+`<p>Un error Monte Carlo estimado igual a cero en un extremo no implica certeza. La simulación contrasta una receta dentro de un generador; la calidad de la medición, los sesgos de información y la identificación causal requieren evidencia adicional.</p>${recordsLink('simulacion','')}`);
}
function mountResearchSimulation(){
  researchMountJointSimulation();
  const rs=D.tables.simulation_metrics.filter(r=>r.estimando===state.simquantity&&[['simN','n'],['simMissing','faltantes'],['simMagnitude','magnitud'],['simCorrelation','correlacion'],['simHeterogeneity','heterogeneidad'],['simEstimator','estimador']].every(([s,k])=>!state[s]||String(r[k])===state[s]));
  const metricLabels={cobertura95:'Cobertura 95 %',sesgo:'Sesgo',rmse:'RMSE',convergencia:'Convergencia',tipo_s:'Error de signo',tipo_m:'Error de magnitud'};
  $('#simulation-reading').innerHTML=notice(`${unique(rs.map(r=>r.k)).length} celdas · ${rs.length} filas de métodos para ${esc(researchPath(state.simquantity))}. Los mismos experimentos aportan varias cantidades y métodos: el número de filas no es el número de repeticiones independientes. ${!rs.length?'No existen celdas con esta combinación. Amplía los filtros.':''}`);
  if(rs.length&&rs.some(r=>Number.isFinite(r[state.simmetric]))){const cellIDs=unique(rs.map(r=>r.k)).sort((a,b)=>a-b);chart('simulation-chart',unique(rs.map(r=>r.estimador)).map((m,i)=>{const a=rs.filter(r=>r.estimador===m&&Number.isFinite(r[state.simmetric]));return {type:'scatter',mode:'markers',name:RESEARCH_ESTIMATORS[m]||m,x:a.map(r=>r.k),y:a.map(r=>r[state.simmetric]),text:a.map(r=>r.clave),customdata:a.map(r=>[r.R,r.R_validas,r.theta]),error_y:{type:'data',array:a.map(r=>Number.isFinite(r[state.simmetric+'_mcse'])?1.96*r[state.simmetric+'_mcse']:0),visible:true},marker:{size:8,color:COLORS[i],opacity:.8},hovertemplate:'Celda %{x}: %{text}<br>Valor=%{y:.4f}<br>Intentos: %{customdata[0]} · válidos: %{customdata[1]}<br>Verdad: %{customdata[2]}<extra>%{fullData.name}</extra>'}}),{xaxis:{title:'Identificador de celda',tickmode:cellIDs.length<25?'array':'auto',tickvals:cellIDs},yaxis:{title:metricLabels[state.simmetric]},...(state.simmetric==='cobertura95'?{shapes:[{type:'line',xref:'paper',x0:0,x1:1,y0:.95,y1:.95,line:{color:'#bc4b3c',dash:'dash'}}]}:{})});}else $('#simulation-chart').innerHTML=notice(rs.length?'Esta medida no tiene valores evaluables para las celdas seleccionadas. Consulta la verdad y la regla de la cantidad; no se muestra como cero.':'Sin celdas para los filtros seleccionados.',true);
  table('simulation-table',rs,{columns:['k','n','magnitud','correlacion','faltantes','heterogeneidad','estimador','estimando','R','R_validas','theta','media','sesgo','sesgo_mcse','rmse','cobertura95','cobertura95_mcse','convergencia','n_significativos','tipo_s','tipo_m'],pageSize:15});
  const jr=D.tables.joint_metrics.filter(r=>r.quantity===state.simspec),different=jr.filter(r=>r.coverage_conditional_denominator!==r.attempts);
  $('#joint-simulation-reading').innerHTML=notice(`${jr.length} filas de escenario y método. ${different.length} tienen menos intervalos válidos que intentos. La tabla permite comparar ambos denominadores y el error Monte Carlo.`,different.length>0);
}

function researchMountJointSimulation(){
  const all=D.tables.joint_metrics;
  if(!all.some(r=>r.quantity===state.simspec))state.simspec='total_indirect';
  const selector=document.querySelector('[data-state="simspec"]');if(selector)selector.value=state.simspec;
  const rs=all.filter(r=>r.quantity===state.simspec),field=state.jointMetric||'coverage_conditional';
  const proportion=['coverage_conditional','coverage_all_attempts','interval_failure'].includes(field);
  const value=r=>proportion?r[field+'_value']:r[field];
  const labels={coverage_conditional:'Cobertura entre intervalos válidos',coverage_all_attempts:'Cobertura sobre todos los intentos',interval_failure:'Proporción sin intervalo válido',bias:'Sesgo',rmse:'RMSE'};
  chart('joint-simulation-chart',unique(rs.map(r=>r.method)).map((method,i)=>{
    const a=rs.filter(r=>r.method===method&&Number.isFinite(value(r)));
    return {type:'scatter',mode:'markers',name:method,x:a.map(value),y:a.map(r=>r.cell),error_x:{type:'data',array:a.map(r=>1.96*(r[proportion?field+'_mcse':'bias_mcse']||0)),visible:field!=='rmse'},customdata:a.map(r=>[r.attempts,r.valid_intervals,r.truth,r.coverage_conditional_denominator,r.coverage_all_attempts_denominator]),marker:{size:9,symbol:['circle','diamond','square'][i%3]},hovertemplate:'%{y}<br>Valor: %{x:.4f}<br>Verdad: %{customdata[2]}<br>Intentos: %{customdata[0]} · intervalos válidos: %{customdata[1]}<br>Denominadores: %{customdata[3]} / %{customdata[4]}<extra>%{fullData.name}</extra>'};
  }),{margin:{l:145,r:25,t:15,b:70},xaxis:{title:labels[field],...(proportion?{range:[-.03,1.03]}:{})},yaxis:{autorange:'reversed'},...(['coverage_conditional','coverage_all_attempts'].includes(field)?{shapes:[{type:'line',yref:'paper',y0:0,y1:1,x0:.95,x1:.95,line:{color:'#bc4b3c',dash:'dash'}}]}:{})});
  table('joint-simulation-table',rs,{columns:['cell','quantity','method','truth','attempts','valid_intervals','coverage_conditional_value','coverage_conditional_numerator','coverage_conditional_denominator','coverage_conditional_mcse','coverage_all_attempts_value','coverage_all_attempts_numerator','coverage_all_attempts_denominator','coverage_all_attempts_mcse','interval_failure_value','bias','bias_mcse','rmse'],pageSize:15});
}

function researchIntervalExample(){return `<svg class="interval-teaching" viewBox="0 0 620 205" role="img" aria-label="Ejemplo didáctico de intervalos: uno positivo, uno que incluye cero y uno negativo"><path d="M310 20V165" stroke="#788d97" stroke-dasharray="5 5"/><g fill="#365568" font-size="16"><text x="302" y="190">0</text><text x="15" y="45">Positiva</text><text x="15" y="95">Incierta</text><text x="15" y="145">Negativa</text></g><g stroke-width="5" stroke-linecap="round"><path d="M365 40H540" stroke="#167c80"/><path d="M240 90H430" stroke="#8295a0"/><path d="M150 140H270" stroke="#b44c53"/></g><g fill="#163e51"><circle cx="450" cy="40" r="7"/><circle cx="345" cy="90" r="7"/><circle cx="205" cy="140" r="7"/></g></svg>`}
function researchMethodologyPage(){
  return heading('Una guía visual para leer el estudio','Del indicador al resultado: qué significa cada cifra, cómo leer una flecha y qué comprobar antes de concluir.')+
    researchProcess([['Población y medida','Identifica países, muestra y codificación de I13.'],['Modelo y cantidad','Distingue una pendiente de un producto de pendientes.'],['Incertidumbre y sensibilidad','Lee el intervalo, el procedimiento y los cambios bajo otras decisiones.']])+
    panel('Primero: ¿qué se está midiendo?',researchConstructs()+`<p>La unidad es el país o territorio. Una asociación nacional no describe automáticamente a pacientes o profesionales. Las puntuaciones resumen indicadores de desarrollo: no son medidas clínicas de efecto ni escalas intercambiables sin comprobación.</p>`)+
    `<div class="guide-chapters"><section class="guide-chapter"><div class="guide-number">b</div><div><h2>Leer una flecha</h2><p>Un coeficiente b expresa cuánto cambia, en promedio y dentro de esa ecuación, la puntuación del destino por una unidad del predictor, manteniendo los otros predictores constantes.</p><div class="formula-explainer"><span>Gobernanza</span><b>→ b = 0,40 →</b><span>Servicios</span></div><p>Ejemplo didáctico: b=0,40 significa 0,40 puntos asociados de servicios por cada punto de gobernanza, bajo el modelo. No significa «un 40 % más» ni que elevar una política cause ese cambio.</p><p>Las flechas de la web siguen la especificación de izquierda a derecha. Una flecha roja indica asociación negativa, no una causalidad en sentido inverso. Una línea discontinua no tiene flecha porque el intervalo incluye cero o no es evaluable.</p>${researchFlowLegend()}</div></section><section class="guide-chapter"><div class="guide-number">IC</div><div><h2>Leer la incertidumbre antes de decidir la dirección</h2>${researchIntervalExample()}<p class="metric-note">Esquema didáctico, no cifras del estudio. El punto es la estimación; la línea es el intervalo.</p><p>Si el intervalo queda a un lado de cero, el procedimiento respalda ese signo. Si atraviesa cero, la dirección no queda resuelta con ese intervalo. Esto no demuestra ausencia de asociación.</p><p>Un IC del 95 % describe el comportamiento del procedimiento en repeticiones bajo sus supuestos; no asigna una probabilidad del 95 % al valor fijo del parámetro. Una p pequeña tampoco mide tamaño, importancia clínica ni probabilidad de que la hipótesis sea verdadera.</p></div></section><section class="guide-chapter"><div class="guide-number">EI</div><div><h2>Pasar de una ruta a un producto indirecto</h2><div class="formula-explainer"><span>Gobernanza</span><b>→ a →</b><span>Acceso</span><b>→ b →</b><span>Servicios</span></div><p>En C1, EI1 = a₁ × b₁ pasa por acceso; EI2 = a₂ × b₂ pasa por capacidad. Ejemplo didáctico: 0,50 × 0,40 = 0,20. Los productos del estudio se calculan dentro de cada imputación: no se reconstruyen multiplicando coeficientes SEM redondeados.</p><div class="quantity-map"><div><strong>EI1 + EI2</strong><p>Suma indirecta: descripción conjunta en C1.</p></div><div><strong>EI1 − EI2</strong><p>Contraste entre vías. Comparar sus p por separado no sustituye este contraste.</p></div><div><strong>Indirecto / total</strong><p>Cociente que puede ser inestable o salir de [0,1]. No es un porcentaje causal mediado.</p></div></div><p>C7 y C9 incluyen un producto serial de tres pendientes. C8 tiene dos raíces: sus productos deben leerse por raíz. Compartir una suma no prueba un orden temporal.</p></div></section><section class="guide-chapter"><div class="guide-number">MI</div><div><h2>Entender qué se hace con los datos ausentes</h2>${researchProcess([['Datos incompletos','Algunos indicadores no están observados en algunos países.'],['Varios conjuntos completados','Se generan versiones plausibles bajo la receta y sus supuestos.'],['Análisis y combinación','Se combina información dentro y entre conjuntos; siguen siendo los mismos países.']])}<p>El principal usa 20 imputaciones. Los coeficientes SEM se combinan con incertidumbre Rubin; los productos tienen su procedimiento bootstrap. Los diagnósticos de medición pueden usar menos conjuntos y lo indican en su vista.</p><p>La muestra «completa» conserva la cohorte original y también puede contener datos ausentes. «Casos completos» es otra operación: retiene solo países con todos los indicadores requeridos. Cambia la selección además del manejo de faltantes.</p></div></section><section class="guide-chapter"><div class="guide-number">B</div><div><h2>Distinguir Rubin, percentil y BCa</h2><div class="quantity-map"><div><strong>Rubin</strong><p>Combina estimaciones y varianzas dentro y entre imputaciones, con los grados de libertad declarados.</p></div><div><strong>Percentil</strong><p>Usa los cuantiles de la distribución de las remuestras.</p></div><div><strong>BCa</strong><p>Ajusta los cuantiles por sesgo y aceleración según su receta.</p></div></div><p>Los intervalos pueden discrepar en si incluyen cero. Informa ambos y explica el procedimiento. No elijas retrospectivamente el que produzca el relato más favorable.</p><p>El bootstrap principal remuestrea los conjuntos ya completados: no vuelve a imputar en cada intento. La cobertura universal bajo datos ausentes no queda garantizada; las simulaciones evalúan generadores concretos.</p></div></section><section class="guide-chapter"><div class="guide-number">R²</div><div><h2>Separar ajuste, predicción y causalidad</h2>${researchVisualExample('prediction')}<p>R² resume variación explicada dentro de muestra. CFI, RMSEA y otros índices comparan aspectos del ajuste bajo las restricciones del modelo. Algunos no son informativos en modelos saturados o con pocos grados de libertad.</p><p>Predecir en países nuevos exige validación fuera de muestra. Explicar un efecto causal requiere además identificar una intervención y controlar los mecanismos de confusión. Un modelo que ajusta bien puede predecir mal o admitir órdenes alternativos.</p></div></section><section class="guide-chapter"><div class="guide-number">↔</div><div><h2>Leer robustez sin contar votos</h2>${researchProcess([['Cambiar una decisión','Semilla, número de imputaciones, codificación, muestra o país omitido.'],['Mirar qué cambia','Signo, magnitud, precisión, aplicabilidad y reparto entre vías.'],['Explicar la dependencia','La estabilidad se limita a las decisiones examinadas; muchas comprobaciones comparten datos.']])}<p>Delta desplaza casillas originalmente ausentes; la omisión de países reutiliza imputaciones fijas. Son diagnósticos puntuales y no intervalos de confianza nuevos. Una observación influyente no tiene por qué ser errónea.</p></div></section></div>`+
    panel('Aplicarlo a un resultado real',`<div class="controls">${units()}${samples()}</div><div id="guide-live-example"></div><button data-go="regiones">Ver todas las casuísticas de esta población</button>`)+
    panel('Un recorrido sencillo de lectura',`<ol class="reading-list"><li><strong>Comprueba el encabezado.</strong> Región, muestra, N, codificación y ejecución ${esc(D.meta.run_id)}.</li><li><strong>Nombra la cantidad.</strong> Coeficiente directo, producto indirecto, suma, contraste o cociente.</li><li><strong>Lee punto e intervalo juntos.</strong> Describe magnitud, signo y precisión sin convertir una imprecisión en cero.</li><li><strong>Comprueba aplicabilidad y denominador.</strong> Un resultado no aplicable conserva un motivo. SEAR tiene N=10 y no supera el mínimo SEM de 15.</li><li><strong>Contrasta decisiones.</strong> Examina sensibilidades, otras casuísticas y calidad de la medida.</li><li><strong>Formula una conclusión proporcionada.</strong> Habla de asociaciones nacionales y de las preguntas que necesitan evidencia temporal o mejores mediciones.</li></ol>`);
}
function mountResearchMethodology(){const r=researchApplication(state.unit,'C1').find(r=>r.quantity==='total_indirect'),el=$('#guide-live-example');if(!r){el.innerHTML=notice('C1 no tiene una estimación aplicable en esta selección. Esto se informa con su motivo y no se representa como cero.',true);return;}el.innerHTML=`<div class="live-reading"><div><span>C1 · suma indirecta · ${esc(unitName(state.unit))}</span><strong>${fmt(r.point)}</strong><span>Percentil 95 % ${researchInterval(r.pct95_low,r.pct95_high)}</span><span>BCa 95 % ${researchInterval(r.bca95_low,r.bca95_high)}</span></div><p>${r.pct95_low>0?'El intervalo percentil queda enteramente por encima de cero.':r.pct95_high<0?'El intervalo percentil queda enteramente por debajo de cero.':'El intervalo percentil incluye cero: la dirección no queda resuelta.'} La magnitud describe una suma de productos de la especificación. No permite afirmar cuánto aumentarían los servicios al aplicar una política.</p></div>`}
